import { paymentMethodLabel } from './paymentMethods.js';

export const DEFAULT_PRINT_BRANDING = {
  primaryColor: '#F2B214',
  darkColor: '#111315',
  textColor: '#111111',
  tagline: 'Precision. Performance. Point.',
  footerThanks: 'شكرًا لثقتكم في POINT',
  showLogo: true,
  showStoreName: true,
  showInvoiceNumber: true,
  showDate: true,
  showCustomer: true,
  showCustomerPhone: true,
  showVehicleOrDevice: true,
  showItems: true,
  showPayment: true,
  showNotes: true,
  showContacts: true,
  showFacebook: true,
  showFacebookQr: true,
  showAddress: true,
  invoiceTitle: 'فاتورة',
  repairTitle: 'فاتورة صيانة',
  receivingTitle: 'إيصال استلام',
  footerText: '',
  facebookUrl: 'https://www.facebook.com/POlNTCenter',
  contactPhone1: '01284285202',
  contactPhone2: '01009613516',
  address: 'بورسعيد محطة موبيل (عتمان) امام الجبانات',
  logoData: 'data:image/jpeg;base64,'
};

export function normalizePrintBranding(settings = {}) {
  return { ...DEFAULT_PRINT_BRANDING, ...(settings.printBranding || {}) };
}

export function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function qrUrl(value, size = 110) {
  if (!value) return '';
  return `https://quickchart.io/qr?size=${size}&margin=2&text=${encodeURIComponent(value)}`;
}

function money(value) {
  return Number(value || 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function dateText(value) {
  if (!value) return '—';
  const d = new Date(value);
  return d.toLocaleString('ar-EG', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
}

export function brandedA4Styles(branding) {
  const p = branding.primaryColor;
  const d = branding.darkColor;
  const t = branding.textColor;
  return `
    @page { size: A4 portrait; margin: 0; }
    * { box-sizing: border-box; }
    html, body { margin:0; padding:0; background:#e6e6e6; }
    body { font-family: Tahoma, Arial, sans-serif; color:${t}; direction:rtl; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
    .page { width:210mm; min-height:297mm; margin:0 auto; background:#fff; position:relative; overflow:hidden; }
    .hero { min-height:69mm; background:${d}; color:#fff; position:relative; padding:10mm 13mm; display:flex; align-items:center; justify-content:space-between; gap:10mm; }
    .hero:after { content:''; position:absolute; inset:0; background:linear-gradient(135deg, rgba(255,255,255,.03), transparent 35%, rgba(242,178,20,.07)); }
    .gold-line { position:absolute; left:0; right:0; bottom:0; height:2mm; background:${p}; z-index:2; }
    .brand { display:flex; align-items:center; gap:5mm; position:relative; z-index:1; min-width:0; }
    .brand-logo { width:38mm; height:38mm; object-fit:cover; object-position:center; background:#0d0e10; border:0.8mm solid #fff; border-radius:5mm; padding:0; display:block; box-shadow:0 2mm 5mm rgba(0,0,0,.25); }
    .brand-fallback { width:38mm; height:38mm; border:1mm solid ${p}; border-radius:4mm; display:flex; align-items:center; justify-content:center; font-weight:900; font-size:15mm; color:${p}; }
    .store-name { font-size:10mm; font-weight:900; letter-spacing:.7mm; white-space:nowrap; }
    .tagline { font-size:3.7mm; color:${p}; font-weight:700; margin-top:1.5mm; }
    .store-meta { font-size:3.6mm; color:#ddd; margin-top:1.2mm; line-height:1.6; max-width:85mm; }
    .doc-badge { position:relative; z-index:1; min-width:51mm; border-right:1mm solid ${p}; padding-right:5mm; text-align:center; }
    .doc-title { font-size:8mm; color:${p}; font-weight:900; }
    .doc-no { margin-top:2.5mm; font-size:4.7mm; font-weight:800; letter-spacing:.3mm; }
    .content { padding:9mm 13mm 29mm; }
    .section-title { font-size:5mm; font-weight:900; margin:0 0 4mm; }
    .meta { display:grid; grid-template-columns:1fr 1fr; border:.35mm solid ${p}; border-radius:4mm; overflow:hidden; margin-bottom:8mm; }
    .meta-card { padding:4mm 5mm; min-height:19mm; border-bottom:.25mm solid #e7e7e7; }
    .meta-card:nth-child(odd) { border-left:.25mm solid #e7e7e7; }
    .meta-card:nth-last-child(-n+2) { border-bottom:0; }
    .meta-label { font-size:3.2mm; color:#777; margin-bottom:1.4mm; }
    .meta-value { font-size:4mm; font-weight:800; }
    .table-wrap, .box { border:.35mm solid #d8d8d8; border-radius:4mm; overflow:hidden; }
    table { width:100%; border-collapse:collapse; font-size:3.7mm; }
    thead { background:${d}; color:#fff; }
    th { padding:3.5mm 2.5mm; font-weight:800; }
    td { padding:3.5mm 2.5mm; border-bottom:.25mm solid #e9e9e9; vertical-align:middle; }
    tbody tr:nth-child(even) { background:#fafafa; }
    .num { text-align:center; direction:ltr; }
    .item { text-align:right; font-weight:700; }
    .currency { color:#777; font-size:3mm; }
    .summary-grid { margin-top:7mm; display:grid; grid-template-columns:1fr 1fr; gap:6mm; align-items:start; }
    .summary-box, .payment-box { border:.35mm solid ${p}; border-radius:4mm; overflow:hidden; }
    .summary-row { display:flex; justify-content:space-between; padding:3mm 4mm; font-size:3.6mm; border-bottom:.25mm solid #e7e7e7; }
    .summary-total { background:${d}; color:#fff; padding:4mm; display:flex; justify-content:space-between; align-items:center; font-size:5mm; font-weight:900; }
    .summary-total b { color:${p}; font-size:6.6mm; }
    .payment-box { padding:4mm; }
    .payment-row { display:flex; justify-content:space-between; gap:4mm; padding:2.2mm 0; font-size:3.7mm; }
    .badge { display:inline-block; background:${p}; color:${d}; font-weight:900; border-radius:999px; padding:1.8mm 4mm; }
    .notes { margin-top:7mm; padding:5mm; }
    .note-line { min-height:9mm; border-bottom:.25mm dashed #ccc; padding:2mm 0; white-space:pre-wrap; }
    .repair-detail { padding:5mm; }
    .repair-grid { display:grid; grid-template-columns:1fr 1fr; gap:4mm 8mm; }
    .repair-item { padding:2.5mm 0; border-bottom:.25mm solid #eee; font-size:3.8mm; }
    .repair-item b { margin-right:3mm; }
    .footer { position:absolute; bottom:0; left:0; right:0; min-height:23mm; background:${d}; color:#fff; border-top:1.6mm solid ${p}; padding:4mm 13mm; display:flex; align-items:center; justify-content:space-between; gap:8mm; }
    .footer-thanks { color:${p}; font-weight:900; font-size:4mm; }
    .footer-text { font-size:3.1mm; color:#ddd; text-align:center; line-height:1.6; }
    .footer-contact { font-size:3.1mm; color:#ddd; line-height:1.7; }
    .social { display:flex; align-items:center; gap:3mm; }
    .social img { width:22mm; height:22mm; background:#fff; border-radius:2mm; padding:1mm; }
    .social-link { direction:ltr; text-align:right; }
    .muted { color:#777; }
    .center { text-align:center; }
    @media print { html,body { background:#fff; } .page { margin:0; } }
  `;
}

function commonHeader(branding, settings, title, number, dateValue) {
  const logoSource = settings.storeLogo || branding.logoData;
  const logo = branding.showLogo && logoSource ? `<img class="brand-logo" src="${escapeHtml(logoSource)}" alt="logo" />` : `<div class="brand-fallback">P</div>`;
  const store = branding.showStoreName ? escapeHtml(settings.storeName || 'POINT') : '';
  const addr = branding.showAddress ? escapeHtml(branding.address || settings.storeAddress || '') : '';
  const phone = branding.showContacts ? [branding.contactPhone1, branding.contactPhone2].filter(Boolean).map(escapeHtml).join('  •  ') : '';
  const badgeNo = branding.showInvoiceNumber ? escapeHtml(number || '—') : '';
  const badgeDate = branding.showDate ? `<div class="doc-no">${escapeHtml(dateText(dateValue))}</div>` : '';
  return `
    <header class="hero">
      <div class="brand">
        ${logo}
        <div>
          ${store ? `<div class="store-name">${store}</div>` : ''}
          ${addr ? `<div class="store-meta">${addr}</div>` : ''}
          ${phone ? `<div class="store-meta">${phone}</div>` : ''}
          <div class="tagline">${escapeHtml(branding.tagline)}</div>
        </div>
      </div>
      <div class="doc-badge">
        <div class="doc-title">${escapeHtml(title)}</div>
        ${badgeNo ? `<div class="doc-no">${badgeNo}</div>` : ''}
        ${badgeDate}
      </div>
      <div class="gold-line"></div>
    </header>`;
}

function commonFooter(branding) {
  const qr = branding.showFacebook && branding.showFacebookQr && branding.facebookUrl ? qrUrl(branding.facebookUrl, 110) : '';
  return `
    <footer class="footer">
      <div>
        <div class="footer-thanks">${escapeHtml(branding.footerThanks)}</div>
        ${branding.footerText ? `<div class="footer-text">${escapeHtml(branding.footerText)}</div>` : ''}
      </div>
      ${branding.showContacts ? `<div class="footer-contact">${escapeHtml(branding.contactPhone1)}<br/>${escapeHtml(branding.contactPhone2)}</div>` : ''}
      ${branding.showFacebook ? `<div class="social">${qr ? `<img src="${qr}" alt="Facebook QR" />` : ''}<div class="social-link"><div>تابعنا على فيسبوك</div><div>${escapeHtml(branding.facebookUrl)}</div></div></div>` : ''}
    </footer>`;
}

export function buildBrandedA4InvoiceHTML(sale, items, settings) {
  const branding = normalizePrintBranding(settings);
  const storeName = escapeHtml(settings.storeName || 'POINT');
  const invoiceNo = sale.invoice_number || '—';
  const customer = sale.customer_name || 'عميل نقدي';
  const customerPhone = sale.customer_phone || '';
  const itemRows = (items || []).map((it, i) => `<tr><td class="num">${i + 1}</td><td class="item">${escapeHtml(it.product_name || '—')}</td><td class="num">${escapeHtml(it.quantity)}</td><td class="num">${money(it.unit_price)} <span class="currency">ج.م</span></td><td class="num"><b>${money(it.total)} <span class="currency">ج.م</span></b></td></tr>`).join('');
  const showMeta = [];
  if (branding.showInvoiceNumber) showMeta.push(`<div class="meta-card"><div class="meta-label">رقم الفاتورة</div><div class="meta-value">${escapeHtml(invoiceNo)}</div></div>`);
  if (branding.showDate) showMeta.push(`<div class="meta-card"><div class="meta-label">التاريخ والوقت</div><div class="meta-value">${escapeHtml(dateText(sale.created_at))}</div></div>`);
  if (branding.showCustomer) showMeta.push(`<div class="meta-card"><div class="meta-label">اسم العميل</div><div class="meta-value">${escapeHtml(customer)}</div></div>`);
  if (branding.showCustomerPhone) showMeta.push(`<div class="meta-card"><div class="meta-label">رقم الهاتف</div><div class="meta-value">${escapeHtml(customerPhone || '—')}</div></div>`);
  if (branding.showVehicleOrDevice) showMeta.push(`<div class="meta-card"><div class="meta-label">السيارة</div><div class="meta-value">${escapeHtml(sale.customer_vehicle_type || '—')}</div></div>`);
  if (branding.showVehicleOrDevice) showMeta.push(`<div class="meta-card"><div class="meta-label">رقم العربية</div><div class="meta-value">${escapeHtml(sale.customer_vehicle_number || '—')}</div></div>`);
  const remaining = Math.max(0, Number(sale.total || 0) - Number(sale.paid_amount || 0));
  return `<!doctype html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"/><title>${storeName} - ${escapeHtml(invoiceNo)}</title><style>${brandedA4Styles(branding)}</style></head><body><div class="page">
    ${commonHeader(branding, settings, branding.invoiceTitle, invoiceNo, sale.created_at)}
    <main class="content">
      ${showMeta.length ? `<h2 class="section-title">بيانات الفاتورة</h2><section class="meta">${showMeta.join('')}</section>` : ''}
      ${branding.showItems ? `<h2 class="section-title">تفاصيل المبيعات</h2><div class="table-wrap"><table><thead><tr><th>م</th><th style="text-align:right">البيان</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${itemRows || '<tr><td colspan="5" class="center">لا توجد أصناف</td></tr>'}</tbody></table></div>` : ''}
      <section class="summary-grid">
        <div class="summary-box"><div class="summary-row"><span>الإجمالي قبل الخصم</span><strong>${money(sale.subtotal)} ج.م</strong></div>${Number(sale.discount) > 0 ? `<div class="summary-row"><span>الخصم</span><strong>-${money(sale.discount)} ج.م</strong></div>` : ''}${Number(sale.tax) > 0 ? `<div class="summary-row"><span>الضريبة</span><strong>${money(sale.tax)} ج.م</strong></div>` : ''}<div class="summary-total"><span>الإجمالي النهائي</span><b>${money(sale.total)} ج.م</b></div></div>
        ${branding.showPayment ? `<div class="payment-box"><div class="section-title" style="margin-bottom:2mm">ملخص الدفع</div><div class="payment-row"><span>طريقة الدفع</span><b>${escapeHtml(paymentMethodLabel(sale.payment_method))}</b></div><div class="payment-row"><span>المدفوع</span><b>${money(sale.paid_amount)} ج.م</b></div><div class="payment-row"><span>المتبقي</span><b>${money(remaining)} ج.م</b></div><div class="payment-row"><span>حالة الدفع</span><span class="badge">${remaining > 0 ? 'متبقي' : 'مدفوع'}</span></div></div>` : ''}
      </section>
      ${branding.showNotes ? `<div class="box notes"><div class="section-title">ملاحظات</div><div class="note-line">${escapeHtml(branding.footerText || 'شكرًا لثقتكم بنا.')}</div></div>` : ''}
    </main>
    ${commonFooter(branding)}
  </div></body></html>`;
}

function repairMeta(repair, branding) {
  const customer = repair.customer_name || repair.customers?.name || '—';
  const type = `${repair.device_type || '—'}${repair.device_model ? ` - ${repair.device_model}` : ''}`;
  const number = repair.repair_number || '—';
  const entries = [
    ['اسم العميل', customer, branding.showCustomer],
    ['رقم الهاتف', repair.customer_phone || repair.customers?.phone || '—', branding.showCustomerPhone],
    ['السيارة', type, branding.showVehicleOrDevice],
    ['رقم العربية', repair.serial_number || '—', branding.showVehicleOrDevice],

    ['رقم الصيانة', number, branding.showInvoiceNumber],
    ['التاريخ', dateText(repair.created_at || repair.updated_at), branding.showDate]
  ];
  return entries.filter(([, , show]) => show).map(([label, value]) => `<div class="repair-item"><span class="muted">${label}</span><b>${escapeHtml(value)}</b></div>`).join('');
}

export function buildBrandedRepairA4HTML(repair, settings, mode = 'receiving', parts = [], payments = []) {
  const branding = normalizePrintBranding(settings);
  const title = mode === 'receiving' ? branding.receivingTitle : branding.repairTitle;
  const number = repair.repair_number || '—';
  const dateValue = mode === 'receiving' ? repair.created_at : (repair.delivered_at || repair.updated_at);
  const detailTitle = mode === 'receiving' ? 'بيانات الاستلام' : 'تفاصيل الصيانة';
  const details = mode === 'receiving'
    ? [['العطل المبلغ عنه', repair.reported_issue], ['حالة الجهاز عند الاستلام', repair.device_condition], ['الملحقات المستلمة', repair.accessories_received], ['ملاحظات', repair.notes]]
    : [['التشخيص', repair.diagnosis], ['الحل / ملاحظات الفني', repair.solution || repair.notes]];
  const validDetails = details.filter(([, v]) => v);
  const partRows = (parts || []).map(p => `<tr><td class="item">${escapeHtml(p.product_name || '—')}</td><td class="num">${escapeHtml(p.quantity)}</td><td class="num">${money(p.unit_price)} ج.م</td><td class="num">${money(p.total)} ج.م</td></tr>`).join('');
  const paymentRows = (payments || []).map(p => `<div class="payment-row"><span>${escapeHtml(p.payment_type === 'deposit' ? 'عربون' : 'دفعة')} — ${escapeHtml(dateText(p.created_at))}</span><b>${money(p.amount)} ج.م</b></div>`).join('');
  return `<!doctype html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"/><title>${escapeHtml(title)} - ${escapeHtml(number)}</title><style>${brandedA4Styles(branding)}</style></head><body><div class="page">
    ${commonHeader(branding, settings, title, number, dateValue)}
    <main class="content">
      <h2 class="section-title">${detailTitle}</h2>
      <div class="box repair-detail"><div class="repair-grid">${repairMeta(repair, branding)}</div></div>
      ${validDetails.length ? `<div class="box" style="margin-top:7mm;padding:5mm"><div class="section-title">${mode === 'receiving' ? 'ملاحظات الاستلام' : 'ملاحظات الصيانة'}</div>${validDetails.map(([label, value]) => `<div class="note-line"><b>${label}:</b> ${escapeHtml(value)}</div>`).join('')}</div>` : ''}
      ${mode === 'delivery' && parts?.length ? `<h2 class="section-title" style="margin-top:7mm">قطع الغيار والخدمات</h2><div class="table-wrap"><table><thead><tr><th style="text-align:right">البيان</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${partRows}</tbody></table></div>` : ''}
      ${mode === 'delivery' ? `<section class="summary-grid" style="margin-top:7mm"><div class="summary-box"><div class="summary-row"><span>تكلفة القطع</span><strong>${money(repair.parts_cost)} ج.م</strong></div><div class="summary-row"><span>العمالة</span><strong>${money(repair.labor_cost)} ج.م</strong></div>${Number(repair.discount) > 0 ? `<div class="summary-row"><span>الخصم</span><strong>-${money(repair.discount)} ج.م</strong></div>` : ''}<div class="summary-total"><span>الإجمالي</span><b>${money(repair.total)} ج.م</b></div></div><div class="payment-box"><div class="section-title">ملخص الدفع</div>${paymentRows}<div class="payment-row"><span>المدفوع</span><b>${money(repair.paid_amount)} ج.م</b></div><div class="payment-row"><span>المتبقي</span><b>${money(repair.remaining_amount)} ج.م</b></div></div></section>` : ''}
    </main>
    ${commonFooter(branding)}
  </div></body></html>`;
}

export { qrUrl };
